refentry.refsect1:
&reftitle.description;

 public mixedYaf_Config_Ini::current


Retourne la valeur de l'entrée de configuration courante durant l'itération. Les valeurs de type tableau sont encapsulées dans un objet Yaf_Config_Abstract.

  &reftitle.examples;

   Exemple avec Yaf_Config_Ini::current


<?php
/**
 * En supposant que /etc/myapp/application.ini contienne :
 * [common]
 * application.name = "MyApp"
 * version          = "1.0"
 */
$config = new Yaf_Config_Ini('/etc/myapp/application.ini', 'common');

$config->rewind();
while ($config->valid()) {
    $value = $config->current();
    if ($value instanceof Yaf_Config_Abstract) {
        echo $config->key(), " => <section de configuration>\n";
    } else {
        echo $config->key(), " => ", $value, "\n";
    }
    $config->next();
}
?>


   &example.outputs.similar;


application => <section de configuration>
version => 1.0
